import { readFileSync } from "fs";
import { join } from "path";

import test from "ava";

import { attachments, attachmentsAsync, extractInvoice, extractInvoiceAsync, PdfDown } from "../index";
import type { InvoiceResult } from "../index";

// ── Fixtures (generated by `cargo run --example gen_fixtures`) ───────────────

const EINVOICE = join(import.meta.dirname, "fixtures", "einvoice");
const fixture = (name: string) => readFileSync(join(EINVOICE, name));

const facturx = fixture("facturx-minimal.pdf");
const ubl = fixture("ubl-attachments.pdf");
const broken = fixture("einvoice-broken.pdf");
const ciiXml = readFileSync(join(EINVOICE, "cii-sample.xml"), "utf8");
const noAttachments = readFileSync(join(import.meta.dirname, "fixtures", "forms", "acroform-basic.pdf"));
const INVOICES = join(import.meta.dirname, "..", "ocr", "__test__", "fixtures");

const expectPresent = <T>(t: { truthy: (v: unknown, m?: string) => void }, v: T | undefined, what: string) => {
  t.truthy(v, `${what} should be present`);
  if (v === undefined) throw new Error(`${what} missing`);
  return v;
};

// ── Attachments ──────────────────────────────────────────────────────────────

test("attachments: Factur-X file is listed once although /AF and /EmbeddedFiles both reference it", (t) => {
  const list = attachments(facturx);
  t.is(list.length, 1);
  const [a] = list;
  t.is(a.name, "factur-x.xml");
  t.is(a.mimeType, "text/xml");
  t.is(a.relationship, "Alternative");
  t.is(a.description, "Factur-X invoice");
  t.is(a.page, undefined);
  t.is(a.size, a.data.length);
  t.is(a.data.toString("utf8"), ciiXml, "FlateDecode payload round-trips byte for byte");
});

test("attachments: /Kids name tree and page-level /FileAttachment annotations", (t) => {
  const list = attachments(ubl);
  t.deepEqual(
    list.map((a) => a.name),
    ["invoice.xml", "readme.txt", "notes.csv"]
  );
  t.is(list[0].mimeType, "application/xml");
  t.is(list[0].relationship, "Data");
  t.is(list[1].description, "Cover note");
  t.is(list[1].page, undefined);
  t.is(list[2].page, 2);
  t.is(list[2].mimeType, "text/csv");
  t.is(list[2].data.toString("utf8"), "line,qty\n1,10\n");
});

test("attachments: documents without embedded files yield an empty array", (t) => {
  t.deepEqual(attachments(noAttachments), []);
});

// ── Invoice extraction from embedded XML ─────────────────────────────────────

test("extractInvoice: Factur-X CII maps header, parties, totals, taxes, payment and lines", (t) => {
  const r = extractInvoice(facturx);
  t.is(r.source, "EmbeddedXml");
  t.is(r.documentType, "Invoice");
  t.is(r.confidence, 1);
  t.deepEqual(r.warnings, []);
  const xml = expectPresent(t, r.embeddedXml, "embeddedXml");
  t.is(xml.filename, "factur-x.xml");
  t.is(xml.standard, "FacturX");
  t.regex(xml.profile ?? "", /factur-x\.eu/);
  t.is(xml.xml, ciiXml);

  const f = r.fields;
  t.is(f.invoiceId?.value, "INV-2026-0042");
  t.is(f.invoiceDate?.value, "2026-11-01");
  t.is(f.invoiceDate?.text, "20261101");
  t.is(f.dueDate?.value, "2026-12-01");
  t.is(f.vendorName?.value, "Acme Aviation Parts GmbH");
  t.deepEqual(f.vendorAddress?.lines, ["Flughafenstrasse 20", "80333 Muenchen", "DE"]);
  t.is(f.vendorTaxId?.value, "DE123456789");
  t.is(f.vendorEmail?.value, "billing@acme-aviation.example");
  t.is(f.customerName?.value, "Jet Support Services, Inc.");
  t.is(f.customerId?.value, "C-1001");
  t.is(f.purchaseOrder?.value, "PO-7788");
  t.is(f.paymentTerm?.value, "Net 30");
  t.is(f.currencyCode, "EUR");
  t.is(f.subTotal?.value, 700);
  t.is(f.totalTax?.value, 133);
  t.is(f.invoiceTotal?.value, 833);
  t.is(f.invoiceTotal?.text, "833.00");
  t.is(f.invoiceTotal?.currencyCode, "EUR");
  t.is(f.invoiceTotal?.confidence, 1);
  t.is(f.invoiceTotal?.span, undefined);
  t.is(f.amountDue?.value, 833);
  t.is(f.previousUnpaidBalance, undefined);
  t.is(f.taxDetails.length, 1);
  t.is(f.taxDetails[0].rate?.value, 19);
  t.is(f.taxDetails[0].base?.value, 700);
  t.is(f.taxDetails[0].category?.value, "S");
  t.is(f.paymentDetails[0].iban?.value, "DE89370400440532013000");
  t.is(f.paymentDetails[0].swift?.value, "COBADEFFXXX");
  t.is(f.items.length, 2);
  t.is(f.items[0].description?.value, "Hydraulic pump seal kit");
  t.is(f.items[0].productCode?.value, "HPS-220");
  t.is(f.items[0].quantity?.value, 4);
  t.is(f.items[0].unit?.value, "H87");
  t.is(f.items[0].unitPrice?.value, 125);
  t.is(f.items[0].taxRate?.value, 19);
  t.is(f.items[0].amount?.value, 500);
  t.is(f.items[1].quantity?.value, 2.5);
  t.is(f.items[1].unit?.value, "HUR");
});

